//! `js-yaml.dump` parity for configuration files (2026-11-19).
//!
//! `yaml-dump.golden` is generated by `tools/oracle/yaml-fixture.mjs` with the
//! pinned `js-yaml` package and its default options, i.e. exactly what
//! upstream `lib/util/yaml.ts` writes.

use serde_json::Value;

use z2m_rs::util::yaml_dump;

fn fixture(name: &str) -> std::path::PathBuf {
    std::path::Path::new(env!("CARGO_MANIFEST_DIR"))
        .join("tests")
        .join("fixtures")
        .join(name)
}

#[test]
fn dump_matches_js_yaml_defaults_byte_for_byte() {
    let json: Value =
        serde_json::from_str(&std::fs::read_to_string(fixture("yaml-dump.json")).unwrap()).unwrap();
    let expected = std::fs::read_to_string(fixture("yaml-dump.golden")).unwrap();
    assert_eq!(yaml_dump::dump(&json), expected);
}

#[test]
fn dump_is_idempotent_after_reading_the_golden_file() {
    let expected = std::fs::read_to_string(fixture("yaml-dump.golden")).unwrap();
    let parsed: Value = serde_yaml_ng::from_str(&expected).unwrap();
    assert_eq!(yaml_dump::dump(&parsed), expected);
}

#[test]
fn write_if_changed_produces_the_node_bytes() {
    let dir = std::env::temp_dir().join(format!(
        "z2m-yaml-dump-{}-{}",
        std::process::id(),
        std::time::SystemTime::now()
            .duration_since(std::time::UNIX_EPOCH)
            .unwrap()
            .as_nanos()
    ));
    std::fs::create_dir_all(&dir).unwrap();
    let path = dir.join("configuration.yaml");
    let expected = std::fs::read_to_string(fixture("yaml-dump.golden")).unwrap();
    let value: Value = serde_yaml_ng::from_str(&expected).unwrap();

    z2m_rs::util::yaml::write_if_changed(&path, &value).unwrap();
    assert_eq!(std::fs::read_to_string(&path).unwrap(), expected);

    // A second write with the same semantic value must not touch the file.
    let before = std::fs::metadata(&path).unwrap().modified().unwrap();
    std::thread::sleep(std::time::Duration::from_millis(20));
    z2m_rs::util::yaml::write_if_changed(&path, &value).unwrap();
    assert_eq!(
        std::fs::metadata(&path).unwrap().modified().unwrap(),
        before
    );
    let _ = std::fs::remove_dir_all(dir);
}
